    public function username_check($username)
{
    //$user_id = $this->session->userdata('user_id'); // Assuming you store the current user ID in the session
    $user_id = $this->uri->segment($this->uri->total_segments());
    // Check if the username exists for any user other than the current user
    $this->load->model('Users_model');
    if ($this->Users_model->is_username_taken($username, $user_id)) {
        $this->form_validation->set_message('username_check', 'The {field} is already taken by another user.');
        return FALSE;
    }
    return TRUE;
}
    /*
     * Editing a tbl_ledger
     */
    function edit($id)
    {
        // check if the tbl_ledger exists before trying to edit it
        $data['tbl_ledger'] = $this->Tbl_ledger_model->get_tbl_ledger($id);
        if (empty($data['tbl_ledger'])) {
            $data['tbl_ledger'] = $this->Tbl_ledger_model->get_tbl_ledger_inact($id);
        }

        if (isset($data['tbl_ledger']['id'])) {
            $this->load->library('form_validation');

            $this->form_validation->set_rules('ledger_name', 'Ledger Name', 'max_length[255]');
            $this->form_validation->set_rules('real_name', 'Real Name', 'max_length[255]');
            // $this->form_validation->set_rules('group', 'Group', 'integer');
            // //$this->form_validation->set_rules('dara_rate', 'Dara Rate', 'integer');
            // $this->form_validation->set_rules('akhar_rate', 'Akhar Rate', 'integer');
            // $this->form_validation->set_rules('owner_name', 'Owner Name', 'max_length[255]');
            $this->form_validation->set_rules('mobile', 'Mobile', 'integer');
            $this->form_validation->set_rules('updated_by', 'Updated By', 'integer');
            // Set validation rule for username with a callback to check uniqueness
            $this->form_validation->set_rules('username', 'Username', 'required|callback_username_check');
            if ($this->form_validation->run()) {   //echo '<pre>'; print_r($_POST); echo '</pre>'; die;
                $params = array(
                    'ledger_name' => $this->input->post('ledger_name'),
                    'username' => $this->input->post('username'),
				'password' => $this->input->post('password'),
                    'real_name' => $this->input->post('real_name'),
                    'parent_id' => $this->input->post('parent_id'),
                    //'group' => $this->input->post('group'),
                    'dara_rate' => $this->input->post('dara_rate'),
                    'akhar_rate' => $this->input->post('akhar_rate'),
                    'owner_name' => $this->input->post('owner_name'),
                    'mobile' => $this->input->post('mobile'),
                    'updated_by' => $this->session->userdata['id'],
                    //'updated_date' => $this->input->post('updated_date'),
                    'dara_commision' => $this->input->post('dara_commision'),
                    'akhar_commission' => $this->input->post('akhar_commission'),
                    //'tp_akhar_commission' => $this->input->post('tp_akhar_commission'),
                    'rebate' => $this->input->post('rebate'),
                    'agent_id' => $this->input->post('tp_r'),
                    'tp_party_id' => $this->input->post('tpparty'),
                    'openingbalance' => $this->input->post('openingbalance'),

                    'hissa' => $this->input->post('hissa'),
                    'hissa_select' => $this->input->post('hissa_select'),
                    'tppercentage' => $this->input->post('tppercentage'),
                    'address' => $this->input->post('address'),
                    'status' => ($this->input->post('isactive') == 'on') ? 1 : 0,
                    //'ismaster' => ($this->input->post('ismaster') == 'on') ? 1 : 0,
                );

                $this->Tbl_ledger_model->update_tbl_ledger($id, $params);
                redirect('/ledger');
            } else {
                //$data['tbl_ledgers'] = $this->Tbl_ledger_model->get_all_tbl_ledger();
                if($_SESSION['role'] == 'Master'){
                    $data['tbl_ledgers'] = $this->Tbl_ledger_model->get_tbl_ledger_byupdatedbyformasters($this->session->userdata['id']);
                }
                elseif($_SESSION['role'] == 'Super Admin'){
                $data['tbl_ledgers'] = $this->Tbl_ledger_model->get_tbl_ledger_byupdatedby($this->session->userdata['id']);
                }
                else{
                    $data['tbl_ledgers'] = $this->Tbl_ledger_model->get_tbl_ledger_byupdatedbyforparty($this->session->userdata['id']);
                }
                $data['shifts'] = $this->Tbl_shift_model->get_all_tbl_shift();
                $data['party'] =  (array)$this->Tbl_ledger_model->get_tbl_ledger_byupdatedby($this->session->userdata['id']);
                //echo '<pre>'; print_r((array)$data['party']); echo '</pre>'; die;
                $data['agent'] = $this->Tbl_agent_model->get_all_tbl_agent();
                $data['_view'] = 'tbl_ledger/edit';
                $this->load->view('layouts/main', $data);
            }
        } else
            show_error('The tbl_ledger you are trying to edit does not exist.');
    }

