    /*
     * Deleting tbl_ledger
     */
    function remove($id)
    {
        $tbl_ledger = $this->Tbl_ledger_model->get_tbl_ledger_delete($id);
        //echo '<pre>'; print_r($tbl_ledger); echo '</pre>'; die;
        // check if the tbl_ledger exists before trying to delete it
        if (isset($tbl_ledger['id'])) {
            $this->Tbl_ledger_model->delete_tbl_ledger($id);
            redirect('/master');
        } else
            show_error('The tbl_ledger you are trying to delete does not exist.');
    }
